// ---------------------------------------------------------------------------
// Procedural fighter art — skeletal, hand-inked, fully vector.
// ---------------------------------------------------------------------------

import { CHARACTERS, POSES } from './data.js';

const R = Math.PI / 180;
const TAU = Math.PI * 2;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

function bone(ctx, a, b, width, color, outline = 3.5) {
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  if (outline > 0) {
    ctx.strokeStyle = 'rgba(12, 8, 16, 0.92)';
    ctx.lineWidth = width + outline;
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.lineTo(b.x, b.y);
    ctx.stroke();
  }
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(a.x, a.y);
  ctx.lineTo(b.x, b.y);
  ctx.stroke();
}

function boneCurve(ctx, a, b, c, width, color, outline = 3.5) {
  ctx.lineCap = 'round';
  if (outline > 0) {
    ctx.strokeStyle = 'rgba(12, 8, 16, 0.92)';
    ctx.lineWidth = width + outline;
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.quadraticCurveTo(b.x, b.y, c.x, c.y);
    ctx.stroke();
  }
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(a.x, a.y);
  ctx.quadraticCurveTo(b.x, b.y, c.x, c.y);
  ctx.stroke();
}

function joint(root, angle, len) {
  const a = angle * R;
  return { x: root.x + Math.sin(a) * len, y: root.y + Math.cos(a) * len };
}

function chain(root, a1, l1, a2, l2) {
  const mid = joint(root, a1, l1);
  const end = joint(mid, a2, l2);
  return { mid, end };
}

function ellipse(ctx, x, y, rx, ry, rot = 0) {
  ctx.beginPath();
  ctx.ellipse(x, y, rx, ry, rot, 0, TAU);
}

function fist(ctx, p, r, color, dark, angle = 0) {
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate(angle);
  ctx.fillStyle = 'rgba(10, 7, 14, 0.95)';
  ellipse(ctx, 0, 0, r + 2.5, r + 2.5);
  ctx.fill();
  const g = ctx.createRadialGradient(-r * 0.3, -r * 0.4, 0, 0, 0, r + 1);
  g.addColorStop(0, color);
  g.addColorStop(1, dark);
  ctx.fillStyle = g;
  ellipse(ctx, 0, 0, r, r);
  ctx.fill();
  ctx.strokeStyle = 'rgba(80, 40, 30, 0.5)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(0, 0, r * 0.55, -0.6, 1.8);
  ctx.stroke();
  ctx.restore();
}

// ---------------------------------------------------------------------------
// arms & legs
// ---------------------------------------------------------------------------
function paintArm(ctx, char, shoulder, angles, back, time, state) {
  const c = char.colors;
  const { mid, end } = chain(shoulder, angles[0], 42, angles[1], 37);
  const shade = back;
  const sleeve = shade ? c.giShade : c.gi;
  const skin = shade ? c.skinShade : c.skin;
  const skinLight = shade ? c.skin : c.skinLight;
  const akane = char.id === 'akane';

  if (akane) {
    // bare arm with a fitted armguard
    bone(ctx, shoulder, mid, 12.5, shade ? c.giDark : c.giShade, 3.5);
    bone(ctx, shoulder, mid, 8, skin, 0);
    const guard = joint(shoulder, angles[0], 38);
    bone(ctx, guard, mid, 11, shade ? c.accentDark : c.accent, 3);
    bone(ctx, mid, end, 9.5, skin, 3.5);
  } else {
    // rolled gi sleeve + bare forearm
    bone(ctx, shoulder, mid, 17, sleeve, 3.8);
    bone(ctx, { x: shoulder.x, y: shoulder.y - 1 }, { x: mid.x, y: mid.y - 1 }, 11, shade ? c.giShade : '#fbf7ec', 0);
    bone(ctx, mid, end, 10, skin, 3.4);
  }

  // wrist wraps
  const wrist = { x: end.x + (mid.x - end.x) * 0.18, y: end.y + (mid.y - end.y) * 0.18 };
  bone(ctx, { x: wrist.x + (mid.x - end.x) * -0.03, y: wrist.y - 2 }, wrist, 10.5, c.wrap, 2.4);
  ctx.strokeStyle = c.trim;
  ctx.lineWidth = 1.2;
  ctx.globalAlpha = 0.8;
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(wrist.x - 4, wrist.y + i * 2.4);
    ctx.lineTo(wrist.x + 4, wrist.y + i * 2.4 + 1);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  const angle = (angles[1] - 90) * R;
  fist(ctx, end, akane ? 6.6 : 7.6, skinLight, skin, angle);

  // shoulder cap
  ctx.fillStyle = shade ? c.giShade : c.gi;
  ctx.strokeStyle = 'rgba(12, 8, 16, 0.9)';
  ctx.lineWidth = 3;
  ellipse(ctx, shoulder.x, shoulder.y, akane ? 8 : 10, akane ? 8 : 10);
  ctx.fill();
  ctx.stroke();
  if (!akane) {
    ctx.strokeStyle = c.accent;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(shoulder.x, shoulder.y, 7, -1.2, 1.2);
    ctx.stroke();
  }
}

function paintLeg(ctx, char, hipRoot, angles, back, time) {
  const c = char.colors;
  const { mid, end } = chain(hipRoot, angles[0], 47, angles[1], 46);
  const akane = char.id === 'akane';
  const pants = back ? c.pantsShade : c.pants;
  const skin = back ? c.skinShade : c.skin;

  // thigh / trousers
  bone(ctx, hipRoot, mid, 23, pants, 4.5);
  // loose cuff
  bone(ctx, { x: mid.x + (hipRoot.x - mid.x) * 0.16, y: mid.y + (hipRoot.y - mid.y) * 0.16 }, mid, 18, back ? c.pants : c.pantsShade, 0);

  // shin
  if (akane) {
    bone(ctx, mid, end, 12, skin, 3.8);
    bone(ctx, { x: mid.x + (end.x - mid.x) * 0.15, y: mid.y + (end.y - mid.y) * 0.15 }, { x: mid.x + (end.x - mid.x) * 0.8, y: mid.y + (end.y - mid.y) * 0.8 }, 12.5, c.pantsShade, 2);
  } else {
    bone(ctx, mid, end, 13, skin, 3.6);
  }

  // ankle wrap
  const ankle = { x: end.x + (mid.x - end.x) * 0.12, y: end.y + (mid.y - end.y) * 0.12 };
  bone(ctx, { x: ankle.x - 4, y: ankle.y - 4 }, ankle, 12, c.wrap, 2.5);
  ctx.strokeStyle = c.trim;
  ctx.lineWidth = 1;
  ctx.globalAlpha = 0.7;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(ankle.x - 5, ankle.y - 3 + i * 2.2);
    ctx.lineTo(ankle.x + 5, ankle.y - 2 + i * 2.2);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // foot
  const footAngle = (angles[1] - 90) * R;
  ctx.save();
  ctx.translate(end.x, end.y + 4);
  ctx.rotate(footAngle);
  ctx.fillStyle = 'rgba(12, 8, 16, 0.95)';
  ellipse(ctx, 2.5, 0, 14, 7.5);
  ctx.fill();
  ctx.fillStyle = akane ? c.giDark : '#201820';
  ellipse(ctx, 2, 0, 12, 5.6);
  ctx.fill();
  ctx.fillStyle = akane ? c.accent : c.trim;
  ctx.globalAlpha = 0.7;
  ellipse(ctx, 6, -0.5, 4, 2.2);
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.restore();
}

// ---------------------------------------------------------------------------
// torso, head
// ---------------------------------------------------------------------------
function paintTorso(ctx, char, hip, lean, time, state, crouching) {
  const c = char.colors;
  const akane = char.id === 'akane';
  ctx.save();
  ctx.translate(hip.x, hip.y);
  ctx.rotate(lean * R);

  // gi skirt / flaps
  const sway = Math.sin(time * 3.4) * 2.2;
  const flap = crouching ? 5 : 1;
  ctx.fillStyle = akane ? c.giDark : c.giShade;
  ctx.strokeStyle = 'rgba(12, 8, 16, 0.9)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-16, -2);
  ctx.quadraticCurveTo(-26 - sway, 12 + flap, -20 - sway, 26 + flap);
  ctx.lineTo(-7, 18);
  ctx.lineTo(0, 0);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(16, -2);
  ctx.quadraticCurveTo(26 + sway, 12 + flap, 20 + sway, 27 + flap);
  ctx.lineTo(7, 18);
  ctx.lineTo(0, 0);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  if (!akane) {
    ctx.strokeStyle = c.giShade;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(-15, 4);
    ctx.quadraticCurveTo(-22, 13, -18, 22);
    ctx.stroke();
  }

  // main torso shape
  const g = ctx.createLinearGradient(-25, -58, 24, 4);
  if (akane) {
    g.addColorStop(0, '#333a60');
    g.addColorStop(0.45, c.gi);
    g.addColorStop(1, c.giDark);
  } else {
    g.addColorStop(0, '#fffbf1');
    g.addColorStop(0.5, c.gi);
    g.addColorStop(1, c.giShade);
  }
  ctx.fillStyle = g;
  ctx.strokeStyle = 'rgba(12, 8, 16, 0.95)';
  ctx.lineWidth = 3.8;
  ctx.beginPath();
  ctx.moveTo(-17, 6);
  ctx.bezierCurveTo(-21, -14, -25, -36, -25, -51);
  ctx.quadraticCurveTo(-24, -60, -15, -61);
  ctx.lineTo(14, -61);
  ctx.quadraticCurveTo(24, -60, 25, -51);
  ctx.bezierCurveTo(25, -36, 21, -14, 17, 6);
  ctx.quadraticCurveTo(0, 12, -17, 6);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // chest opening / collar
  if (akane) {
    ctx.fillStyle = c.skinShade;
    ctx.beginPath();
    ctx.moveTo(-9, -60);
    ctx.lineTo(0, -32);
    ctx.lineTo(9, -60);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = c.accent;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-10, -59);
    ctx.lineTo(0, -31);
    ctx.lineTo(10, -59);
    ctx.stroke();
    ctx.strokeStyle = c.accent;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(-24, -49);
    ctx.quadraticCurveTo(-6, -36, 0, -31);
    ctx.quadraticCurveTo(7, -37, 25, -49);
    ctx.stroke();
  } else {
    // crossed lapels
    ctx.fillStyle = '#2a1b1c';
    ctx.beginPath();
    ctx.moveTo(-9, -61);
    ctx.lineTo(0, -34);
    ctx.lineTo(9, -61);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#fffaf0';
    ctx.strokeStyle = c.giShade;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(-11, -60);
    ctx.lineTo(2, -28);
    ctx.lineTo(16, -55);
    ctx.lineTo(19, -47);
    ctx.lineTo(2, -21);
    ctx.lineTo(-16, -54);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.strokeStyle = c.accent;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-17, -54);
    ctx.quadraticCurveTo(-7, -31, 1, -22);
    ctx.stroke();
  }

  // fabric folds
  ctx.strokeStyle = akane ? 'rgba(0,0,0,0.3)' : 'rgba(120,100,80,0.35)';
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.moveTo(-16, -46);
  ctx.quadraticCurveTo(-10, -28, -11, -12);
  ctx.moveTo(15, -42);
  ctx.quadraticCurveTo(12, -24, 13, -10);
  ctx.stroke();

  // belt / sash
  const belt = akane ? c.accent : c.accent;
  ctx.fillStyle = belt;
  ctx.strokeStyle = 'rgba(12, 8, 16, 0.85)';
  ctx.lineWidth = 2.4;
  roundRectLocal(ctx, -18, -10, 36, 8, 2.5);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = akane ? '#ff8db8' : '#ef6a64';
  ctx.globalAlpha = 0.55;
  ctx.fillRect(-17, -9.5, 34, 1.6);
  ctx.globalAlpha = 1;

  // knot and trailing ribbons
  ctx.fillStyle = belt;
  ctx.strokeStyle = 'rgba(12, 8, 16, 0.8)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-5, -5);
  ctx.lineTo(4, -8);
  ctx.lineTo(6, -2);
  ctx.lineTo(-3, 1);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  const wave = Math.sin(time * 4.2) * 3.2;
  ctx.fillStyle = belt;
  ctx.strokeStyle = 'rgba(12, 8, 16, 0.8)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-8, -4);
  ctx.quadraticCurveTo(-27, -2 + wave, -38, 8 + wave);
  ctx.lineTo(-37, 14 + wave);
  ctx.quadraticCurveTo(-23, 4 + wave, -8, 2);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-7, -6);
  ctx.quadraticCurveTo(-20, -16 + wave, -34, -12 + wave);
  ctx.lineTo(-36, -5 + wave);
  ctx.quadraticCurveTo(-21, -8 + wave, -7, -1);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // trim on the leading edge
  ctx.strokeStyle = akane ? c.accent : c.trim;
  ctx.lineWidth = 1.4;
  ctx.globalAlpha = 0.75;
  ctx.beginPath();
  ctx.moveTo(-24, -47);
  ctx.quadraticCurveTo(-19, -18, -15, 4);
  ctx.stroke();
  ctx.globalAlpha = 1;

  ctx.restore();
}

function roundRectLocal(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

function paintHead(ctx, char, head, lean, headTilt, time, state) {
  const c = char.colors;
  const akane = char.id === 'akane';
  const ang = (headTilt * 0.6 + lean * 0.18) * R;

  ctx.save();
  ctx.translate(head.x, head.y);
  ctx.rotate(ang);

  // hair mass behind head / ponytail
  ctx.fillStyle = c.hair;
  ctx.strokeStyle = 'rgba(10, 7, 14, 0.9)';
  ctx.lineWidth = 2.4;
  if (akane) {
    const sw = Math.sin(time * 3.2) * 4;
    ctx.beginPath();
    ctx.moveTo(-10, -8);
    ctx.bezierCurveTo(-35, -20, -62, 4 + sw, -49, 38 + sw);
    ctx.bezierCurveTo(-44, 52 + sw, -30, 58 + sw, -22, 46 + sw);
    ctx.bezierCurveTo(-32, 30 + sw, -23, 10 + sw, -5, 1);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // ponytail highlight
    ctx.strokeStyle = c.hairLight;
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.7;
    ctx.beginPath();
    ctx.moveTo(-28, -5);
    ctx.quadraticCurveTo(-47, 16 + sw, -39, 43 + sw);
    ctx.stroke();
    ctx.globalAlpha = 1;
    // ribbon tails
    ctx.fillStyle = c.accent;
    ctx.strokeStyle = 'rgba(10, 7, 14, 0.8)';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(-13, -8);
    ctx.quadraticCurveTo(-34, -4 + sw * 0.5, -42, 9 + sw);
    ctx.lineTo(-36, 13 + sw);
    ctx.quadraticCurveTo(-25, 2 + sw * 0.4, -12, -2);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-12, -5);
    ctx.quadraticCurveTo(-31, -15 + sw * 0.5, -43, -6 + sw);
    ctx.lineTo(-38, 0 + sw);
    ctx.quadraticCurveTo(-25, -8 + sw * 0.4, -11, 0);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  } else {
    ellipse(ctx, -2, -2, 18, 19);
    ctx.fill();
    ctx.stroke();
    // spiky back hair
    ctx.beginPath();
    ctx.moveTo(-17, -2);
    ctx.lineTo(-27, -11);
    ctx.lineTo(-22, 2);
    ctx.lineTo(-28, 9);
    ctx.lineTo(-15, 10);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // headband tails
    const wave = Math.sin(time * 4.4) * 3.8;
    ctx.fillStyle = c.accent;
    ctx.strokeStyle = 'rgba(10, 7, 14, 0.8)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(-13, -7);
    ctx.quadraticCurveTo(-32, -4 + wave, -46, 5 + wave);
    ctx.lineTo(-44, 9 + wave);
    ctx.quadraticCurveTo(-28, 1 + wave, -13, 0);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-13, -9);
    ctx.quadraticCurveTo(-30, -15 + wave, -43, -12 + wave);
    ctx.lineTo(-45, -7 + wave);
    ctx.quadraticCurveTo(-28, -8 + wave, -13, -2);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }

  // neck
  ctx.strokeStyle = 'rgba(10, 7, 14, 0.9)';
  ctx.lineWidth = 9;
  ctx.beginPath();
  ctx.moveTo(-1, 12);
  ctx.lineTo(0, 22);
  ctx.stroke();
  ctx.strokeStyle = c.skinShade;
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(-1, 12);
  ctx.lineTo(0, 21);
  ctx.stroke();

  // face
  const fg = ctx.createLinearGradient(-13, -14, 14, 16);
  fg.addColorStop(0, c.skinLight);
  fg.addColorStop(0.55, c.skin);
  fg.addColorStop(1, c.skinShade);
  ctx.fillStyle = fg;
  ctx.strokeStyle = 'rgba(10, 7, 14, 0.95)';
  ctx.lineWidth = 2.6;
  ctx.beginPath();
  ctx.moveTo(-13, -10);
  ctx.quadraticCurveTo(-15, 4, -9, 12);
  ctx.quadraticCurveTo(-2, 19, 8, 15);
  ctx.quadraticCurveTo(15, 10, 15, 1);
  ctx.quadraticCurveTo(15, -11, 8, -15);
  ctx.quadraticCurveTo(-5, -19, -13, -10);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // ear
  ctx.fillStyle = c.skinShade;
  ctx.beginPath();
  ctx.ellipse(-11, 1, 3.4, 5, -0.2, 0, TAU);
  ctx.fill();
  ctx.stroke();

  // hair front / fringe
  ctx.fillStyle = c.hair;
  ctx.strokeStyle = 'rgba(10, 7, 14, 0.9)';
  ctx.lineWidth = 2;
  if (akane) {
    ctx.beginPath();
    ctx.moveTo(-14, -8);
    ctx.quadraticCurveTo(-10, -21, 4, -19);
    ctx.quadraticCurveTo(16, -17, 17, -8);
    ctx.quadraticCurveTo(6, -13, -3, -10);
    ctx.quadraticCurveTo(-8, -8, -12, 2);
    ctx.lineTo(-15, 1);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.strokeStyle = c.hairLight;
    ctx.lineWidth = 1.7;
    ctx.beginPath();
    ctx.moveTo(-8, -16);
    ctx.quadraticCurveTo(2, -12, 10, -14);
    ctx.stroke();
    // ribbon knot
    ctx.fillStyle = c.accent;
    ctx.strokeStyle = 'rgba(10, 7, 14, 0.8)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.ellipse(-13, -9, 4.5, 3.2, 0.5, 0, TAU);
    ctx.fill();
    ctx.stroke();
  } else {
    ctx.beginPath();
    ctx.moveTo(-14, -9);
    ctx.quadraticCurveTo(-9, -22, 4, -19);
    ctx.quadraticCurveTo(15, -18, 18, -9);
    ctx.quadraticCurveTo(10, -14, 3, -11);
    ctx.lineTo(-1, -16);
    ctx.lineTo(-4, -9);
    ctx.lineTo(-8, -13);
    ctx.lineTo(-11, -4);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // headband
    ctx.strokeStyle = c.accent;
    ctx.lineWidth = 3.6;
    ctx.beginPath();
    ctx.moveTo(-12, -7);
    ctx.quadraticCurveTo(0, -10, 13, -6);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(10, 7, 14, 0.7)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-12, -8.6);
    ctx.quadraticCurveTo(0, -11.7, 13, -7.6);
    ctx.stroke();
  }

  // brows, eyes, mouth
  ctx.strokeStyle = c.eye;
  ctx.fillStyle = c.eye;
  ctx.lineCap = 'round';
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(-4, -3.5);
  ctx.quadraticCurveTo(0, -5.5, 4, -3.5);
  ctx.stroke();
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.moveTo(5, -3);
  ctx.quadraticCurveTo(10, -5.5, 14, -2);
  ctx.stroke();

  // eye
  ctx.fillStyle = '#fbf5ec';
  ctx.beginPath();
  ctx.ellipse(8.5, 0.8, 3.6, 2.4, -0.1, 0, TAU);
  ctx.fill();
  ctx.fillStyle = c.eye;
  ctx.beginPath();
  ctx.arc(8.2, 0.7, 1.6, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.9)';
  ctx.beginPath();
  ctx.arc(7.7, 0.1, 0.55, 0, TAU);
  ctx.fill();

  // far eye hint
  ctx.fillStyle = c.eye;
  ctx.globalAlpha = 0.8;
  ctx.beginPath();
  ctx.ellipse(0.5, 0.6, 1.9, 1.1, 0, 0, TAU);
  ctx.fill();
  ctx.globalAlpha = 1;

  // nose + mouth
  ctx.strokeStyle = c.skinShade;
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(13.5, 3);
  ctx.lineTo(11.5, 5.2);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(70, 30, 30, 0.85)';
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.moveTo(5.5, 10.5);
  ctx.quadraticCurveTo(8.5, 11.5, 11, 10);
  ctx.stroke();

  // cheek / jaw shading
  ctx.fillStyle = 'rgba(120, 50, 40, 0.12)';
  ctx.beginPath();
  ctx.moveTo(9, 6);
  ctx.quadraticCurveTo(4, 13, -2, 12);
  ctx.quadraticCurveTo(5, 8, 9, 6);
  ctx.fill();

  ctx.restore();
}

// ---------------------------------------------------------------------------
// full character paint (local space, feet at 0,0)
// ---------------------------------------------------------------------------
export function paintFighter(ctx, char, pose, opts = {}) {
  const time = opts.time ?? 0;
  const crouching = Boolean(opts.crouching);
  const state = opts.state || 'idle';

  const hip = { x: 0, y: -92 + pose.hipY };
  const leanRad = pose.lean * R;
  const neck = {
    x: hip.x + Math.sin(leanRad) * 56,
    y: hip.y - Math.cos(leanRad) * 56
  };
  const headAng = leanRad + pose.head * R;
  const head = {
    x: neck.x + Math.sin(headAng) * 29,
    y: neck.y - Math.cos(headAng) * 29
  };
  const shF = { x: neck.x + 3, y: neck.y + 5 };
  const shB = { x: neck.x - 5, y: neck.y + 6 };
  const hipF = { x: hip.x + 7, y: hip.y + 2 };
  const hipB = { x: hip.x - 7, y: hip.y + 2 };

  const legB = chain(hipB, pose.legB[0], 47, pose.legB[1], 46);
  const legF = chain(hipF, pose.legF[0], 47, pose.legF[1], 46);
  const armB = chain(shB, pose.armB[0], 42, pose.armB[1], 37);
  const armF = chain(shF, pose.armF[0], 42, pose.armF[1], 37);

  // aura bloom behind the body
  if (opts.aura) {
    const g = ctx.createRadialGradient(hip.x, hip.y - 40, 4, hip.x, hip.y - 40, 92);
    g.addColorStop(0, opts.aura);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = opts.auraAlpha ?? 0.22;
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(hip.x, hip.y - 40, 60, 96, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  paintArm(ctx, char, shB, pose.armB, true, time, state);
  paintLeg(ctx, char, hipB, pose.legB, true, time);
  paintTorso(ctx, char, hip, pose.lean, time, state, crouching);
  paintLeg(ctx, char, hipF, pose.legF, false, time);
  paintHead(ctx, char, head, pose.lean, pose.head, time, state);
  paintArm(ctx, char, shF, pose.armF, false, time, state);
}

// ---------------------------------------------------------------------------
// world-space fighter draw
// ---------------------------------------------------------------------------
export function drawFighter(ctx, fighter, time, options = {}) {
  const char = CHARACTERS[fighter.charId];
  ctx.save();
  ctx.translate(fighter.x, fighter.y);
  if (fighter.state === 'knockdown' && fighter.grounded) {
    ctx.translate(0, -14);
    ctx.rotate(-1.18);
    ctx.translate(0, 14);
  }
  if (fighter.spinAngle) {
    ctx.translate(0, -92);
    ctx.rotate(fighter.spinAngle);
    ctx.translate(0, 92);
  }
  ctx.scale(fighter.facing, 1);

  if (fighter.flash > 0.12) {
    const f = 1 + fighter.flash * 1.4;
    ctx.filter = `brightness(${f.toFixed(2)}) saturate(${(1 - fighter.flash * 0.55).toFixed(2)})`;
  }

  paintFighter(ctx, char, fighter.pose, {
    time,
    state: fighter.state,
    crouching: fighter.crouching,
    aura: fighter.char.colors.aura,
    auraAlpha: 0.06 + (fighter.spirit / MAX_SPIRIT_SAFE) * 0.16
  });

  ctx.filter = 'none';
  ctx.restore();
}

const MAX_SPIRIT_SAFE = 100;

// snapshot afterimage
export function drawFighterSnapshot(ctx, snap, time) {
  const char = CHARACTERS[snap.charId];
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = Math.max(0, snap.life / snap.maxLife) * snap.alpha;
  ctx.translate(snap.x, snap.y);
  if (snap.state === 'knockdown' && snap.grounded) ctx.rotate(-1.18);
  if (snap.spinAngle) {
    ctx.translate(0, -92);
    ctx.rotate(snap.spinAngle);
    ctx.translate(0, 92);
  }
  ctx.scale(snap.facing, 1);
  ctx.filter = 'blur(0.4px)';
  paintFighter(ctx, char, snap.pose, {
    time,
    state: 'attack',
    crouching: snap.crouching,
    aura: snap.color,
    auraAlpha: 0.25
  });
  ctx.filter = 'none';
  ctx.restore();
}

// ---------------------------------------------------------------------------
// character portraits used by the selection cards
// ---------------------------------------------------------------------------
export function renderPortrait(canvas, charId) {
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const CW = 280;
  const CH = 330;
  if (canvas.width !== CW * dpr) {
    canvas.width = CW * dpr;
    canvas.height = CH * dpr;
  }
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, CW, CH);

  const char = CHARACTERS[charId];
  const c = char.colors;

  // atmosphere
  const bg = ctx.createLinearGradient(0, 0, 0, CH);
  bg.addColorStop(0, charId === 'kaito' ? '#25101b' : '#0d1830');
  bg.addColorStop(0.55, '#0b0911');
  bg.addColorStop(1, '#07060b');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, CW, CH);

  const halo = ctx.createRadialGradient(CW / 2, 150, 10, CW / 2, 150, 155);
  halo.addColorStop(0, charId === 'kaito' ? 'rgba(230, 80, 60, 0.38)' : 'rgba(80, 190, 255, 0.28)');
  halo.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, CW, CH);

  // giant kanji watermark
  ctx.save();
  ctx.font = `180px ${'"IPAGothic","WenQuanYi Zen Hei",serif'}`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = charId === 'kaito' ? 'rgba(214,60,74,0.13)' : 'rgba(100,216,255,0.1)';
  ctx.fillText(char.kanji, CW / 2, 158);
  ctx.restore();

  // rising sun / moon band
  ctx.save();
  ctx.globalAlpha = 0.28;
  const sun = ctx.createRadialGradient(CW / 2, 145, 0, CW / 2, 145, 88);
  sun.addColorStop(0, charId === 'kaito' ? '#f7b45c' : '#8fe5ff');
  sun.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = sun;
  ctx.fillRect(0, 40, CW, 220);
  ctx.restore();

  // ground shadow
  const sh = ctx.createRadialGradient(CW / 2, 306, 8, CW / 2, 306, 84);
  sh.addColorStop(0, 'rgba(0,0,0,0.7)');
  sh.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = sh;
  ctx.beginPath();
  ctx.ellipse(CW / 2, 306, 82, 17, 0, 0, TAU);
  ctx.fill();

  ctx.save();
  ctx.translate(CW / 2 - 2, 306);
  ctx.scale(1.44, 1.44);
  paintFighter(ctx, char, POSES.idle, {
    time: 0.4,
    state: 'idle',
    aura: c.aura,
    auraAlpha: 0.12
  });
  ctx.restore();

  // petals
  for (let i = 0; i < 7; i++) {
    const x = (i * 47 + 30) % CW;
    const y = (i * 71 + 24) % 240;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(i + 0.4);
    ctx.globalAlpha = 0.25 + (i % 3) * 0.12;
    ctx.fillStyle = charId === 'kaito' ? '#ffb7a3' : '#b6eaff';
    ctx.beginPath();
    ctx.ellipse(0, 0, 2.2, 4.2, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  // vignette
  const vig = ctx.createRadialGradient(CW / 2, CH / 2, 90, CW / 2, CH / 2, 220);
  vig.addColorStop(0, 'rgba(0,0,0,0)');
  vig.addColorStop(1, 'rgba(0,0,0,0.45)');
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, CW, CH);
}

// ---------------------------------------------------------------------------
// Stage art — a sunset temple veranda above a sea of cloud.
// ---------------------------------------------------------------------------

import { W, H, GROUND, WORLD_W, CHARACTERS, STAGE } from './data.js';

const TAU = Math.PI * 2;
const R = Math.PI / 180;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

function seeded(seed) {
  let a = seed >>> 0;
  return () => {
    a += 0x6D2B79F5;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function softEllipse(ctx, x, y, rx, ry, color, alpha = 1, rot = 0) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, Math.max(rx, ry));
  g.addColorStop(0, color);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(x, y, rx, ry, rot, 0, TAU);
  ctx.fill();
  ctx.restore();
}

// ---------------------------------------------------------------------------
// parallax clouds / mountains / town
// ---------------------------------------------------------------------------
const CLOUDS = (() => {
  const rng = seeded(77);
  return Array.from({ length: 9 }, (_, i) => ({
    x: -180 + rng() * (W + 360),
    y: 90 + rng() * 260,
    rx: 90 + rng() * 210,
    ry: 12 + rng() * 30,
    a: 0.05 + rng() * 0.1,
    f: 0.04 + rng() * 0.08
  }));
})();

const BIRDS = (() => {
  const rng = seeded(19);
  return Array.from({ length: 8 }, () => ({
    x: 120 + rng() * 900,
    y: 120 + rng() * 140,
    s: 3 + rng() * 4,
    f: 0.1 + rng() * 0.1,
    p: rng() * TAU
  }));
})();

const distantTown = (() => {
  const rng = seeded(211);
  return Array.from({ length: 16 }, (_, i) => ({
    x: 60 + i * 78 + rng() * 28,
    w: 28 + rng() * 38,
    h: 18 + rng() * 36,
    roof: rng() > 0.55
  }));
})();

export function drawBackground(ctx, game) {
  const cam = game.cam.x;
  const t = game.time;

  // ----------------------------- sky
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0, '#0d0a1b');
  sky.addColorStop(0.22, '#24122e');
  sky.addColorStop(0.42, '#55243e');
  sky.addColorStop(0.58, '#a64549');
  sky.addColorStop(0.69, '#e88155');
  sky.addColorStop(0.755, '#f8b877');
  sky.addColorStop(0.8, '#7d3f42');
  sky.addColorStop(1, '#1a0e18');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  // sun with soft halo
  const sunX = 936 - (cam - 800) * 0.1;
  const sunY = 246;
  const halo = ctx.createRadialGradient(sunX, sunY, 20, sunX, sunY, 300);
  halo.addColorStop(0, 'rgba(255, 224, 160, 0.48)');
  halo.addColorStop(0.35, 'rgba(255, 160, 95, 0.18)');
  halo.addColorStop(1, 'rgba(255, 120, 80, 0)');
  ctx.fillStyle = halo;
  ctx.fillRect(sunX - 320, sunY - 320, 640, 640);

  ctx.save();
  ctx.beginPath();
  ctx.arc(sunX, sunY, 92, 0, TAU);
  ctx.clip();
  const disc = ctx.createLinearGradient(0, sunY - 92, 0, sunY + 92);
  disc.addColorStop(0, '#fff9dc');
  disc.addColorStop(0.45, '#ffe0a6');
  disc.addColorStop(0.72, '#ffb96e');
  disc.addColorStop(1, '#ec7f50');
  ctx.fillStyle = disc;
  ctx.fillRect(sunX - 100, sunY - 100, 200, 200);
  ctx.fillStyle = 'rgba(92, 42, 55, 0.26)';
  [0.18, 0.46, 0.64].forEach((p, i) => {
    ctx.fillRect(sunX - 110, sunY - 90 + p * 180, 220, 7 + i * 3);
  });
  ctx.restore();

  // cloud bands
  for (const c of CLOUDS) {
    const x = ((c.x - (cam - 800) * c.f) % (W + 500) + W + 500) % (W + 500) - 200;
    softEllipse(ctx, x, c.y, c.rx, c.ry, c.y < 280 ? '#f7b38d' : '#6b3553', c.a, 0);
  }

  // birds
  ctx.strokeStyle = 'rgba(38, 18, 34, 0.55)';
  ctx.lineWidth = 1.4;
  for (const b of BIRDS) {
    const x = ((b.x - (cam - 800) * b.f + t * 5) % (W + 200) + W + 200) % (W + 200) - 100;
    const y = b.y + Math.sin(t * 0.8 + b.p) * 4;
    ctx.beginPath();
    ctx.moveTo(x - b.s, y);
    ctx.quadraticCurveTo(x - b.s * 0.4, y - b.s * 0.7, x, y - b.s * 0.15);
    ctx.quadraticCurveTo(x + b.s * 0.4, y - b.s * 0.7, x + b.s, y);
    ctx.stroke();
  }

  // ----------------------------- far mountains
  drawRidge(ctx, cam, 0.1, 476, 46, '#6b3a52', 0.55, 31);
  drawFuji(ctx, cam);
  drawRidge(ctx, cam, 0.18, 502, 36, '#43243d', 0.8, 73);
  drawRidge(ctx, cam, 0.25, 528, 26, '#2a1731', 0.95, 127);

  // fog at the base of the mountains
  const fog = ctx.createLinearGradient(0, 455, 0, 560);
  fog.addColorStop(0, 'rgba(240, 138, 95, 0.0)');
  fog.addColorStop(0.45, 'rgba(240, 138, 105, 0.16)');
  fog.addColorStop(1, 'rgba(35, 18, 36, 0.7)');
  ctx.fillStyle = fog;
  ctx.fillRect(0, 455, W, 120);

  // ----------------------------- distant town + pagoda
  drawDistantTown(ctx, cam);
  drawPagoda(ctx, 196 - (cam - 800) * 0.24, 534);
  drawTorii(ctx, 1166 - (cam - 800) * 0.24, 526);

  // warm horizon glow under the town
  const under = ctx.createLinearGradient(0, 500, 0, 610);
  under.addColorStop(0, 'rgba(255, 161, 104, 0.12)');
  under.addColorStop(1, 'rgba(13, 7, 17, 0)');
  ctx.fillStyle = under;
  ctx.fillRect(0, 500, W, 110);
}

function drawRidge(ctx, cam, factor, base, amp, color, alpha, seed) {
  const shift = (cam - 800) * factor;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(-200, H);
  for (let x = -200; x <= W + 200; x += 18) {
    const wx = x + shift;
    const y = base - amp * (0.45 + 0.35 * Math.sin(wx * 0.0041 + seed) + 0.2 * Math.sin(wx * 0.011 + seed * 2.4));
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W + 200, H);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawFuji(ctx, cam) {
  const cx = 1010 - (cam - 800) * 0.14;
  const baseY = 474;
  const apexY = 304;
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(cx - 280, baseY);
  ctx.quadraticCurveTo(cx - 130, 450, cx - 62, apexY + 20);
  ctx.quadraticCurveTo(cx - 26, apexY - 8, cx, apexY);
  ctx.quadraticCurveTo(cx + 28, apexY - 8, cx + 64, apexY + 20);
  ctx.quadraticCurveTo(cx + 140, 448, cx + 300, baseY);
  ctx.closePath();
  const g = ctx.createLinearGradient(0, apexY, 0, baseY);
  g.addColorStop(0, '#5d3550');
  g.addColorStop(0.45, '#47273e');
  g.addColorStop(1, '#2e1934');
  ctx.fillStyle = g;
  ctx.fill();

  // snow cap
  ctx.beginPath();
  ctx.moveTo(cx - 64, apexY + 22);
  ctx.quadraticCurveTo(cx - 24, apexY - 6, cx, apexY);
  ctx.quadraticCurveTo(cx + 28, apexY - 6, cx + 68, apexY + 22);
  ctx.lineTo(cx + 48, apexY + 30);
  ctx.lineTo(cx + 33, apexY + 20);
  ctx.lineTo(cx + 18, apexY + 42);
  ctx.lineTo(cx + 4, apexY + 25);
  ctx.lineTo(cx - 12, apexY + 46);
  ctx.lineTo(cx - 27, apexY + 26);
  ctx.lineTo(cx - 44, apexY + 36);
  ctx.closePath();
  ctx.fillStyle = 'rgba(255, 226, 210, 0.58)';
  ctx.fill();

  // rim light
  ctx.strokeStyle = 'rgba(255, 170, 120, 0.25)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(cx - 280, baseY);
  ctx.quadraticCurveTo(cx - 130, 450, cx - 62, apexY + 20);
  ctx.quadraticCurveTo(cx - 26, apexY - 8, cx, apexY);
  ctx.stroke();
  ctx.restore();
}

function drawDistantTown(ctx, cam) {
  const shift = (cam - 800) * 0.24;
  ctx.save();
  ctx.globalAlpha = 0.92;
  for (const h of distantTown) {
    const x = h.x - shift;
    if (x < -80 || x > W + 80) continue;
    ctx.fillStyle = '#1b1025';
    ctx.fillRect(x, 530 - h.h, h.w, h.h + 40);
    if (h.roof) {
      ctx.beginPath();
      ctx.moveTo(x - 7, 530 - h.h);
      ctx.lineTo(x + h.w / 2, 530 - h.h - 12);
      ctx.lineTo(x + h.w + 7, 530 - h.h);
      ctx.closePath();
      ctx.fill();
    }
    // tiny warm windows
    ctx.fillStyle = 'rgba(255, 170, 92, 0.5)';
    for (let i = 0; i < 2; i++) {
      if ((h.w * i + h.h) % 3 > 1.2) ctx.fillRect(x + 6 + i * 13, 530 - h.h + 10, 4, 6);
    }
  }
  ctx.restore();
}

function drawPagoda(ctx, x, baseY) {
  ctx.save();
  ctx.translate(x, baseY);
  ctx.fillStyle = '#1a0f24';
  ctx.strokeStyle = 'rgba(255, 152, 100, 0.11)';
  ctx.lineWidth = 1.5;
  const tiers = 4;
  for (let i = 0; i < tiers; i++) {
    const w = 92 - i * 15;
    const y = -i * 48;
    // body
    ctx.fillRect(-w * 0.34, y - 34, w * 0.68, 34);
    // eaves
    ctx.beginPath();
    ctx.moveTo(-w / 2 - 12, y - 34);
    ctx.quadraticCurveTo(-w / 2, y - 44, -w / 2 + 6, y - 45);
    ctx.lineTo(w / 2 - 6, y - 45);
    ctx.quadraticCurveTo(w / 2, y - 44, w / 2 + 12, y - 34);
    ctx.quadraticCurveTo(w / 4, y - 28, 0, y - 27);
    ctx.quadraticCurveTo(-w / 4, y - 28, -w / 2 - 12, y - 34);
    ctx.closePath();
    ctx.fill();
    // tiny window light
    ctx.fillStyle = 'rgba(255, 173, 95, 0.42)';
    ctx.fillRect(-3, y - 20, 6, 8);
    ctx.fillStyle = '#1a0f24';
  }
  // spire
  ctx.fillRect(-2, -tiers * 48 - 22, 4, 42);
  ctx.beginPath();
  ctx.arc(0, -tiers * 48 - 25, 5, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawTorii(ctx, x, y) {
  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = '#1c0f24';
  ctx.strokeStyle = 'rgba(255, 160, 110, 0.13)';
  ctx.lineWidth = 1;
  // posts
  ctx.fillRect(-62, -150, 11, 152);
  ctx.fillRect(52, -150, 11, 152);
  // crossbars
  ctx.beginPath();
  ctx.moveTo(-98, -158);
  ctx.quadraticCurveTo(0, -176, 98, -158);
  ctx.lineTo(94, -146);
  ctx.quadraticCurveTo(0, -162, -94, -146);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.fillRect(-78, -124, 156, 9);
  ctx.fillRect(-4, -142, 8, 20);
  // hanging lantern
  const sway = Math.sin(performance.now() * 0.0012) * 2;
  ctx.globalAlpha = 0.85;
  ctx.fillStyle = 'rgba(255, 179, 94, 0.35)';
  ctx.beginPath();
  ctx.arc(sway, -112, 14, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#ffbd6d';
  roundRect(ctx, -7 + sway, -122, 14, 18, 5);
  ctx.fill();
  ctx.fillStyle = '#1c0f24';
  ctx.fillRect(-5 + sway, -126, 10, 4);
  ctx.fillRect(-5 + sway, -106, 10, 3);
  ctx.restore();
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

// ---------------------------------------------------------------------------
// cherry trees (precomputed clusters)
// ---------------------------------------------------------------------------
const TREE = (() => {
  const rng = seeded(941);
  const blossoms = [];
  for (let i = 0; i < 78; i++) {
    const a = rng() * TAU;
    const rad = rng();
    let x;
    let y;
    if (rng() < 0.6) {
      x = 40 + rng() * 200;
      y = -230 - rng() * 150;
    } else {
      x = 10 + rng() * 90;
      y = -120 - rng() * 170;
    }
    blossoms.push({
      x, y, r: 8 + rng() * 16, tone: rng(), a: 0.35 + rng() * 0.5,
      phase: rng() * TAU
    });
  }
  return { blossoms };
})();

function drawCherryTree(ctx, game, x, mirror, time) {
  ctx.save();
  ctx.translate(x, GROUND + 14);
  ctx.scale(mirror, 1);

  // trunk
  const trunkGrad = ctx.createLinearGradient(0, 0, 90, -280);
  trunkGrad.addColorStop(0, '#1a0e16');
  trunkGrad.addColorStop(0.5, '#2e1a22');
  trunkGrad.addColorStop(1, '#3a2230');
  ctx.strokeStyle = 'rgba(8, 5, 10, 0.9)';
  ctx.lineWidth = 37;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.bezierCurveTo(8, -60, 10, -120, 38, -180);
  ctx.bezierCurveTo(58, -226, 92, -250, 120, -294);
  ctx.stroke();
  ctx.strokeStyle = trunkGrad;
  ctx.lineWidth = 30;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.bezierCurveTo(8, -60, 10, -120, 38, -180);
  ctx.bezierCurveTo(58, -226, 92, -250, 120, -294);
  ctx.stroke();

  // main branches
  const branches = [
    [[26, -152], [88, -190], [150, -214], 9],
    [[44, -190], [10, -236], [-28, -266], 7],
    [[72, -230], [130, -248], [190, -240], 8],
    [[96, -258], [80, -320], [52, -360], 6],
    [[118, -292], [168, -320], [216, -330], 5],
    [[60, -218], [58, -280], [96, -318], 5]
  ];
  for (const [a, b, c, w] of branches) {
    ctx.strokeStyle = 'rgba(8, 5, 10, 0.9)';
    ctx.lineWidth = w + 4;
    ctx.beginPath();
    ctx.moveTo(a[0], a[1]);
    ctx.quadraticCurveTo(b[0], b[1], c[0], c[1]);
    ctx.stroke();
    ctx.strokeStyle = '#291821';
    ctx.lineWidth = w;
    ctx.beginPath();
    ctx.moveTo(a[0], a[1]);
    ctx.quadraticCurveTo(b[0], b[1], c[0], c[1]);
    ctx.stroke();
  }

  // blossoms
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const b of TREE.blossoms) {
    const swayX = Math.sin(time * 0.7 + b.phase) * 2.2;
    const swayY = Math.cos(time * 0.55 + b.phase) * 1.4;
    const bx = b.x + swayX;
    const by = b.y + swayY;
    const alpha = b.a * 0.26;
    const g = ctx.createRadialGradient(bx, by, 0, bx, by, b.r * 1.6);
    g.addColorStop(0, `rgba(255, 190, 210, ${alpha})`);
    g.addColorStop(1, 'rgba(255, 120, 160, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(bx, by, b.r * 1.6, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  for (const b of TREE.blossoms) {
    const swayX = Math.sin(time * 0.7 + b.phase) * 2.2;
    const swayY = Math.cos(time * 0.55 + b.phase) * 1.4;
    const bx = b.x + swayX;
    const by = b.y + swayY;
    const tone = b.tone;
    const col = tone < 0.35 ? '#ffd2dc' : tone < 0.7 ? '#f6a9bd' : '#e98ba8';
    ctx.fillStyle = col;
    ctx.globalAlpha = b.a;
    ctx.beginPath();
    ctx.ellipse(bx, by, b.r * 0.72, b.r * 0.5, b.phase, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = b.a * 0.7;
    ctx.beginPath();
    ctx.ellipse(bx + b.r * 0.28, by - b.r * 0.22, b.r * 0.32, b.r * 0.22, b.phase + 1, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  // few glowing lanterns inside tree
  const lanterns = [[150, -210, 0.8], [212, -232, 0.55]];
  for (const [lx, ly, a] of lanterns) {
    const sway = Math.sin(time * 1.3 + lx) * 3;
    const g = ctx.createRadialGradient(lx + sway, ly + 16, 2, lx + sway, ly + 16, 36);
    g.addColorStop(0, `rgba(255, 191, 110, ${0.35 * a})`);
    g.addColorStop(1, 'rgba(255, 150, 70, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(lx + sway, ly + 16, 36, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#f7b567';
    ctx.globalAlpha = 0.85;
    roundRect(ctx, lx - 5 + sway, ly + 10, 10, 13, 4);
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  ctx.restore();
}

// ---------------------------------------------------------------------------
// veranda, railing, lanterns
// ---------------------------------------------------------------------------
export function drawStage(ctx, game) {
  const t = game.time;

  // trees behind railing
  drawCherryTree(ctx, game, 96, 1, t);
  drawCherryTree(ctx, game, WORLD_W - 96, -1, t);

  drawRailing(ctx, t);
  drawFloor(ctx, t);
  drawLanternStrings(ctx, t);
  drawStoneLantern(ctx, 338, GROUND + 2, 1, t);
  drawStoneLantern(ctx, WORLD_W - 338, GROUND + 2, -1, t);
}

function drawRailing(ctx, t) {
  const y = 520;
  // posts
  for (let x = 0; x <= WORLD_W; x += 158) {
    const g = ctx.createLinearGradient(x, y, x + 14, GROUND);
    g.addColorStop(0, '#5e3a2c');
    g.addColorStop(0.5, '#3e261f');
    g.addColorStop(1, '#251318');
    ctx.fillStyle = g;
    ctx.fillRect(x, y, 14, GROUND - y + 4);
    ctx.fillStyle = 'rgba(216,176,106,0.3)';
    ctx.fillRect(x, y, 14, 2.5);
    ctx.fillStyle = 'rgba(10,6,12,0.5)';
    ctx.fillRect(x + 11, y + 4, 2, GROUND - y);
  }
  // top and middle rails
  const rail = ctx.createLinearGradient(0, y - 4, 0, y + 14);
  rail.addColorStop(0, '#7a4c34');
  rail.addColorStop(0.5, '#4a2c23');
  rail.addColorStop(1, '#26141a');
  ctx.fillStyle = rail;
  ctx.fillRect(0, y - 4, WORLD_W, 13);
  ctx.fillStyle = 'rgba(255, 205, 130, 0.22)';
  ctx.fillRect(0, y - 4, WORLD_W, 2);
  ctx.fillStyle = 'rgba(10, 6, 12, 0.65)';
  ctx.fillRect(0, y + 9, WORLD_W, 2);
  ctx.fillStyle = '#3c241e';
  ctx.fillRect(0, y + 34, WORLD_W, 7);

  // small hanging lanterns on the rail
  for (let x = 82; x < WORLD_W; x += 236) {
    const sway = Math.sin(t * 1.2 + x * 0.01) * 2;
    glow(ctx, x + sway, y + 52, 34, 'rgba(255, 170, 90, 0.22)');
    ctx.fillStyle = '#f2a95f';
    ctx.strokeStyle = 'rgba(60,25,22,0.7)';
    ctx.lineWidth = 1.5;
    roundRect(ctx, x - 6 + sway, y + 43, 12, 17, 5);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#26141a';
    ctx.fillRect(x - 4 + sway, y + 40, 8, 3);
    ctx.fillRect(x - 4 + sway, y + 60, 8, 2);
    ctx.strokeStyle = 'rgba(40, 22, 22, 0.8)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x + sway, y + 29);
    ctx.lineTo(x + sway, y + 40);
    ctx.stroke();
  }
}

function drawFloor(ctx, t) {
  const g = ctx.createLinearGradient(0, GROUND - 6, 0, 780);
  g.addColorStop(0, '#5d3829');
  g.addColorStop(0.18, '#43271f');
  g.addColorStop(0.65, '#26151a');
  g.addColorStop(1, '#120a12');
  ctx.fillStyle = g;
  ctx.fillRect(0, GROUND - 4, WORLD_W, 220);

  // perspective plank lines
  ctx.save();
  ctx.globalAlpha = 0.28;
  ctx.strokeStyle = '#0d070e';
  ctx.lineWidth = 1.4;
  for (let i = -10; i <= 10; i++) {
    const xTop = 800 + i * 92;
    const xBot = 800 + i * 210;
    ctx.beginPath();
    ctx.moveTo(xTop, GROUND);
    ctx.lineTo(xBot, 820);
    ctx.stroke();
  }
  ctx.globalAlpha = 0.16;
  ctx.strokeStyle = '#ffc98a';
  for (let i = -9; i <= 9; i += 2) {
    ctx.beginPath();
    ctx.moveTo(800 + i * 94 + 12, GROUND + 3);
    ctx.lineTo(800 + i * 214 + 16, 820);
    ctx.stroke();
  }
  ctx.restore();

  // horizontal seams
  ctx.strokeStyle = 'rgba(8, 5, 10, 0.55)';
  ctx.lineWidth = 2;
  [GROUND + 26, GROUND + 62, GROUND + 108].forEach((y, i) => {
    ctx.globalAlpha = 0.4 - i * 0.08;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(WORLD_W, y);
    ctx.stroke();
  });
  ctx.globalAlpha = 1;

  // front edge / gold rope line
  const edge = ctx.createLinearGradient(0, GROUND - 10, 0, GROUND + 8);
  edge.addColorStop(0, 'rgba(255, 218, 150, 0.7)');
  edge.addColorStop(1, 'rgba(120, 67, 40, 0.1)');
  ctx.fillStyle = edge;
  ctx.fillRect(0, GROUND - 7, WORLD_W, 4);
  ctx.fillStyle = 'rgba(8, 5, 10, 0.55)';
  ctx.fillRect(0, GROUND - 2, WORLD_W, 2);

  // rope knots
  for (let x = 20; x < WORLD_W; x += 46) {
    ctx.fillStyle = 'rgba(230, 190, 120, 0.18)';
    ctx.beginPath();
    ctx.arc(x, GROUND - 5, 3.2, 0, TAU);
    ctx.fill();
  }

  // warm pools of light cast by the lanterns
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let x = 82; x < WORLD_W; x += 236) {
    const g2 = ctx.createRadialGradient(x, GROUND + 20, 4, x, GROUND + 20, 120);
    g2.addColorStop(0, 'rgba(255, 163, 80, 0.10)');
    g2.addColorStop(1, 'rgba(255, 120, 60, 0)');
    ctx.fillStyle = g2;
    ctx.beginPath();
    ctx.ellipse(x, GROUND + 20, 130, 46, 0, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawLanternStrings(ctx, t) {
  const strings = [
    { x0: -120, x1: 1720, y: 268, sag: 52, start: 0 },
    { x0: 120, x1: 1480, y: 336, sag: 38, start: 1 }
  ];
  for (let s = 0; s < strings.length; s++) {
    const st = strings[s];
    ctx.strokeStyle = 'rgba(26, 14, 18, 0.75)';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    for (let x = st.x0; x <= st.x1; x += 20) {
      const p = (x - st.x0) / (st.x1 - st.x0);
      const y = st.y + Math.sin(p * Math.PI) * st.sag;
      if (x === st.x0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    const gap = 184;
    for (let x = st.x0 + 80 + s * 40; x < st.x1; x += gap) {
      const p = (x - st.x0) / (st.x1 - st.x0);
      const y = st.y + Math.sin(p * Math.PI) * st.sag;
      const sway = Math.sin(t * 1.1 + x * 0.017) * 3;
      const ly = y + 22 + Math.cos(t * 0.9 + x) * 1.2;
      glow(ctx, x + sway, ly, 44, 'rgba(255, 170, 88, 0.24)');
      ctx.fillStyle = '#f6ad63';
      ctx.strokeStyle = 'rgba(74, 30, 22, 0.6)';
      ctx.lineWidth = 1.4;
      roundRect(ctx, x - 9 + sway, ly - 12, 18, 26, 6);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = '#361b1a';
      ctx.fillRect(x - 7 + sway, ly - 15, 14, 4);
      ctx.fillRect(x - 7 + sway, ly + 13, 14, 3);
      ctx.strokeStyle = 'rgba(50, 24, 22, 0.8)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x + sway, y);
      ctx.lineTo(x + sway, ly - 15);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(74, 30, 22, 0.7)';
      ctx.beginPath();
      ctx.moveTo(x + sway, ly + 16);
      ctx.lineTo(x + sway, ly + 23);
      ctx.stroke();
    }
  }
}

function drawStoneLantern(ctx, x, y, dir, t) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(dir, 1);
  const g = ctx.createLinearGradient(-24, -110, 24, 0);
  g.addColorStop(0, '#4c4650');
  g.addColorStop(0.5, '#2f2a35');
  g.addColorStop(1, '#19141e');
  ctx.fillStyle = g;
  ctx.strokeStyle = 'rgba(8, 5, 10, 0.8)';
  ctx.lineWidth = 2;
  // base
  ctx.beginPath();
  ctx.moveTo(-26, 0); ctx.lineTo(26, 0); ctx.lineTo(19, -12); ctx.lineTo(-19, -12); ctx.closePath();
  ctx.fill(); ctx.stroke();
  // stem
  ctx.fillRect(-7, -58, 14, 48);
  ctx.strokeRect(-7, -58, 14, 48);
  // light box
  roundRect(ctx, -18, -92, 36, 34, 4);
  ctx.fill(); ctx.stroke();
  // roof
  ctx.beginPath();
  ctx.moveTo(-27, -92); ctx.quadraticCurveTo(0, -108, 27, -92); ctx.lineTo(18, -86); ctx.lineTo(-18, -86); ctx.closePath();
  ctx.fill(); ctx.stroke();
  // warm window
  glow(ctx, 0, -75, 38, 'rgba(255, 168, 84, 0.28)');
  ctx.fillStyle = '#f6b565';
  ctx.globalAlpha = 0.85;
  roundRect(ctx, -9, -84, 18, 18, 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.restore();
}

function glow(ctx, x, y, r, color) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, color);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Effects & atmosphere — shadows, petals, fireballs, sparks.
// ---------------------------------------------------------------------------

import { W, H, GROUND, WORLD_W, CHARACTERS } from './data.js';

const TAU = Math.PI * 2;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

export function drawFighterShadow(ctx, fighter) {
  const height = Math.max(0, GROUND - fighter.y);
  const squash = clamp(1 - height / 520, 0.32, 1);
  const rx = (fighter.state === 'knockdown' ? 74 : 48) * squash;
  const ry = 12 * squash;
  const alpha = 0.38 * squash;
  const g = ctx.createRadialGradient(fighter.x, GROUND + 2, 1, fighter.x, GROUND + 2, rx * 1.3);
  g.addColorStop(0, `rgba(5, 3, 8, ${alpha})`);
  g.addColorStop(1, 'rgba(5, 3, 8, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(fighter.x, GROUND + 2, rx * 1.3, ry * 1.8, 0, 0, TAU);
  ctx.fill();
}

// ---------------------------------------------------------------------------
// ambient petals and embers
// ---------------------------------------------------------------------------
export function drawAmbient(ctx, game, layer) {
  const isFront = layer === 'front';
  for (const p of game.ambient) {
    const front = p.z >= 0.8;
    if (front !== isFront) continue;
    if (p.kind === 'ember') {
      const a = 0.25 + 0.35 * p.z;
      const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, 5 + p.z * 4);
      g.addColorStop(0, `rgba(255, 205, 120, ${a})`);
      g.addColorStop(0.4, `rgba(255, 125, 45, ${a * 0.7})`);
      g.addColorStop(1, 'rgba(255, 90, 20, 0)');
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(p.x, p.y, 5 + p.z * 5, 0, TAU);
      ctx.fill();
      ctx.restore();
    } else {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.angle);
      const s = 0.65 + p.z * 0.9;
      ctx.scale(s, s);
      ctx.globalAlpha = 0.45 + p.z * 0.32;
      ctx.fillStyle = p.z > 0.9 ? '#ffd0dd' : '#f5a9be';
      ctx.beginPath();
      ctx.moveTo(0, -6);
      ctx.bezierCurveTo(5, -4, 5, 3, 0, 7);
      ctx.bezierCurveTo(-4, 4, -5, -3, 0, -6);
      ctx.fill();
      ctx.globalAlpha *= 0.55;
      ctx.fillStyle = '#ff91ad';
      ctx.beginPath();
      ctx.ellipse(1.6, 0, 1.6, 3.2, 0.5, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }
}

// ---------------------------------------------------------------------------
// projectiles
// ---------------------------------------------------------------------------
export function drawProjectile(ctx, p, time) {
  const dir = Math.sign(p.vx) || 1;

  // trail
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = p.trail.length - 1; i >= 0; i--) {
    const t = 1 - i / p.trail.length;
    const pt = p.trail[i];
    const r = (p.super ? 54 : 16) * t * (0.7 + Math.sin(time * 30 + i) * 0.06);
    if (r <= 0.5) continue;
    const g = ctx.createRadialGradient(pt.x, pt.y, 0, pt.x, pt.y, r);
    g.addColorStop(0, hexA(p.color2, 0.22 * t));
    g.addColorStop(0.5, hexA(p.color, 0.14 * t));
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(pt.x, pt.y, r, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  if (p.super) {
    drawSuperBeam(ctx, p, time);
    return;
  }

  ctx.save();
  ctx.translate(p.x, p.y);
  const wobble = Math.sin(time * 28 + p.tick) * 0.08;
  ctx.rotate(wobble);

  // glow field
  const glow = ctx.createRadialGradient(0, 0, 2, 0, 0, 68);
  glow.addColorStop(0, hexA(p.color2, 0.55));
  glow.addColorStop(0.3, hexA(p.color, 0.35));
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(0, 0, 68, 0, TAU);
  ctx.fill();

  if (p.charId === 'kaito') {
    // flame petals licking off the core
    for (let i = 0; i < 7; i++) {
      const a = i / 7 * TAU + time * 7;
      const r = 18 + Math.sin(time * 20 + i * 1.7) * 8;
      ctx.save();
      ctx.rotate(a);
      ctx.translate(r, 0);
      const fg = ctx.createLinearGradient(0, 0, -32, 0);
      fg.addColorStop(0, hexA('#fff3c4', 0.95));
      fg.addColorStop(0.4, hexA(p.color2, 0.85));
      fg.addColorStop(1, 'rgba(255, 60, 10, 0)');
      ctx.fillStyle = fg;
      ctx.beginPath();
      ctx.moveTo(4, 0);
      ctx.quadraticCurveTo(-14, -10, -30 - Math.sin(time * 18 + i) * 5, 0);
      ctx.quadraticCurveTo(-14, 10, 4, 0);
      ctx.fill();
      ctx.restore();
    }
  } else {
    // icy crystal shards
    for (let i = 0; i < 6; i++) {
      const a = i / 6 * TAU - time * 3;
      ctx.save();
      ctx.rotate(a);
      ctx.translate(30 + Math.sin(time * 12 + i) * 4, 0);
      ctx.fillStyle = hexA(p.color2, 0.8);
      ctx.beginPath();
      ctx.moveTo(0, -9);
      ctx.lineTo(4, 0);
      ctx.lineTo(0, 9);
      ctx.lineTo(-4, 2);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
  }
  ctx.restore();

  // core
  const core = ctx.createRadialGradient(-4, -5, 1, 0, 0, 25);
  core.addColorStop(0, '#ffffff');
  core.addColorStop(0.3, p.color2);
  core.addColorStop(0.75, p.color);
  core.addColorStop(1, hexA(p.color, 0.1));
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = core;
  ctx.beginPath();
  ctx.arc(0, 0, 23 + Math.sin(time * 26) * 1.5, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = hexA('#ffffff', 0.65);
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(0, 0, 27, 0, TAU);
  ctx.stroke();
  ctx.restore();

  // little orbiting sparks
  for (let i = 0; i < 4; i++) {
    const a = time * 6 + i * TAU / 4;
    const r = 30 + Math.sin(time * 10 + i) * 6;
    ctx.fillStyle = hexA(p.color2, 0.8);
    ctx.beginPath();
    ctx.arc(Math.cos(a) * r, Math.sin(a) * r, 1.8, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawSuperBeam(ctx, p, time) {
  const dir = Math.sign(p.vx) || 1;
  const char = CHARACTERS[p.charId];
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.scale(dir, 1);

  // massive trailing wake
  const wake = ctx.createLinearGradient(-320, 0, 90, 0);
  wake.addColorStop(0, 'rgba(0,0,0,0)');
  wake.addColorStop(0.4, hexA(p.color, 0.12));
  wake.addColorStop(0.75, hexA(p.color2, 0.3));
  wake.addColorStop(1, hexA('#ffffff', 0.55));
  ctx.fillStyle = wake;
  ctx.beginPath();
  ctx.moveTo(-330, 0);
  ctx.quadraticCurveTo(-80, -8, 60, -58);
  ctx.quadraticCurveTo(96, 0, 60, 58);
  ctx.quadraticCurveTo(-80, 8, -330, 0);
  ctx.fill();

  // outer body
  const outer = ctx.createRadialGradient(0, 0, 4, 0, 0, 120);
  outer.addColorStop(0, hexA(p.color2, 0.95));
  outer.addColorStop(0.4, hexA(p.color, 0.7));
  outer.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = outer;
  ctx.beginPath();
  ctx.ellipse(0, 0, 118, 78 + Math.sin(time * 12) * 4, 0, 0, TAU);
  ctx.fill();

  // streaming ribbons
  for (let k = 0; k < 3; k++) {
    ctx.strokeStyle = hexA(k === 1 ? '#ffffff' : p.color2, 0.4 + k * 0.12);
    ctx.lineWidth = 4 - k;
    ctx.beginPath();
    for (let x = -190; x <= 70; x += 8) {
      const ph = x * 0.035 + time * 7 + k * 2.1;
      const y = Math.sin(ph) * (22 + k * 9);
      if (x === -190) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  // core
  const core = ctx.createLinearGradient(-110, 0, 90, 0);
  core.addColorStop(0, hexA(p.color2, 0.1));
  core.addColorStop(0.55, hexA('#ffffff', 0.9));
  core.addColorStop(1, '#ffffff');
  ctx.fillStyle = core;
  ctx.beginPath();
  ctx.ellipse(8, 0, 88, 34 + Math.sin(time * 20) * 2, 0, 0, TAU);
  ctx.fill();

  // kanji seal
  ctx.globalAlpha = 0.38;
  ctx.fillStyle = '#ffffff';
  ctx.font = `700 58px "IPAGothic","WenQuanYi Zen Hei",serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(char.kanji, -8, 2);
  ctx.globalAlpha = 1;

  // orbit shards / embers
  for (let i = 0; i < 10; i++) {
    const a = time * 4 + i * TAU / 10;
    const rx = 70 + Math.sin(time * 8 + i) * 20;
    const ry = 42 + Math.cos(time * 9 + i) * 16;
    ctx.fillStyle = hexA(i % 2 ? p.color2 : '#ffffff', 0.6);
    ctx.beginPath();
    ctx.arc(Math.cos(a) * rx, Math.sin(a) * ry, 2.2, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // leading edge flare
  ctx.strokeStyle = hexA('#ffffff', 0.8);
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(70, 0, 66, -1.2, 1.2);
  ctx.stroke();
  ctx.restore();
}

// ---------------------------------------------------------------------------
// particles
// ---------------------------------------------------------------------------
export function drawFx(ctx, game) {
  for (const e of game.fx) {
    const life = e.life / e.maxLife;
    if (e.type === 'dust') {
      const r = e.size * (0.7 + (1 - life) * 1.8);
      const g = ctx.createRadialGradient(e.x, e.y, 0, e.x, e.y, r);
      g.addColorStop(0, `rgba(206, 180, 143, ${life * 0.3})`);
      g.addColorStop(1, 'rgba(180, 150, 110, 0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(e.x, e.y, r, 0, TAU);
      ctx.fill();
      continue;
    }

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';

    if (e.type === 'spark') {
      const len = 2 + Math.hypot(e.vx || 0, e.vy || 0) * 1.8;
      ctx.strokeStyle = hexA(e.color, life);
      ctx.lineWidth = Math.max(0.6, e.size * life);
      ctx.lineCap = 'round';
      const mag = Math.hypot(e.vx || 0, e.vy || 0) || 1;
      ctx.beginPath();
      ctx.moveTo(e.x, e.y);
      ctx.lineTo(e.x - (e.vx / mag) * len, e.y - (e.vy / mag) * len);
      ctx.stroke();
      ctx.fillStyle = hexA('#ffffff', life * 0.9);
      ctx.beginPath();
      ctx.arc(e.x, e.y, Math.max(0.5, e.size * 0.55 * life), 0, TAU);
      ctx.fill();
    } else if (e.type === 'shard') {
      ctx.translate(e.x, e.y);
      ctx.rotate(e.rot || 0);
      ctx.fillStyle = hexA(e.color, life);
      ctx.beginPath();
      ctx.moveTo(-e.size, -e.size * 0.5);
      ctx.lineTo(e.size, 0);
      ctx.lineTo(-e.size * 0.2, e.size * 0.7);
      ctx.closePath();
      ctx.fill();
    } else if (e.type === 'flash') {
      const r = e.size * (1.6 - life * 0.6);
      const g = ctx.createRadialGradient(e.x, e.y, 0, e.x, e.y, r);
      g.addColorStop(0, `rgba(255,255,245,${life})`);
      g.addColorStop(0.3, hexA(e.color, life * 0.85));
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(e.x, e.y, r, 0, TAU);
      ctx.fill();
    } else if (e.type === 'ring') {
      const prog = 1 - life;
      const r = e.size + prog * e.size * 3.2;
      ctx.strokeStyle = hexA(e.color, life * 0.9);
      ctx.lineWidth = Math.max(1, 6 * life);
      ctx.beginPath();
      ctx.arc(e.x, e.y, r, 0, TAU);
      ctx.stroke();
      ctx.strokeStyle = hexA('#ffffff', life * 0.5);
      ctx.lineWidth = Math.max(0.6, 2 * life);
      ctx.beginPath();
      ctx.arc(e.x, e.y, r * 0.82, 0, TAU);
      ctx.stroke();
    } else if (e.type === 'star') {
      const prog = 1 - life;
      const r = e.size * (0.7 + prog * 1.5);
      ctx.translate(e.x, e.y);
      ctx.rotate(e.rot || 0);
      ctx.fillStyle = hexA(e.color, life * 0.8);
      ctx.beginPath();
      for (let i = 0; i < 8; i++) {
        const a = i / 8 * TAU;
        const rr = i % 2 === 0 ? r : r * 0.24;
        ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
      }
      ctx.closePath();
      ctx.fill();
    } else if (e.type === 'auraRing') {
      const prog = 1 - life;
      ctx.strokeStyle = hexA(e.color, life * 0.75);
      ctx.lineWidth = 3 * life + 1;
      ctx.beginPath();
      ctx.arc(e.x, e.y, 30 + prog * 150, 0, TAU);
      ctx.stroke();
      ctx.strokeStyle = hexA('#ffffff', life * 0.4);
      ctx.beginPath();
      ctx.arc(e.x, e.y, 18 + prog * 110, 0, TAU);
      ctx.stroke();
    }

    ctx.restore();
  }
}

function hexA(hex, alpha) {
  if (!hex) return `rgba(255,255,255,${alpha})`;
  if (hex.startsWith('rgba')) return hex;
  let h = hex.replace('#', '');
  if (h.length === 3) h = h.split('').map((c) => c + c).join('');
  const n = parseInt(h, 16);
  const r = (n >> 16) & 255;
  const g = (n >> 8) & 255;
  const b = n & 255;
  return `rgba(${r},${g},${b},${clamp(alpha, 0, 1)})`;
}

// ---------------------------------------------------------------------------
// HUD, banners, and screen treatment
// ---------------------------------------------------------------------------

import { W, H, CHARACTERS, MAX_HEALTH, MAX_SPIRIT, STAGE } from './data.js';

const TAU = Math.PI * 2;
const R = Math.PI / 180;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const FONT = '"Lato", "DejaVu Sans", system-ui, sans-serif';
const SERIF = '"DejaVu Serif", Georgia, serif';
const JP = '"IPAGothic", "WenQuanYi Zen Hei", "DejaVu Sans", serif';

const hudState = {
  key: '',
  trail: [MAX_HEALTH, MAX_HEALTH],
  ready: [0, 0],
  flash: [0, 0]
};

function hexA(hex, alpha) {
  if (!hex) return `rgba(255,255,255,${alpha})`;
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${clamp(alpha, 0, 1)})`;
}

function poly(ctx, pts, close = true) {
  ctx.beginPath();
  pts.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)));
  if (close) ctx.closePath();
}

function diamond(ctx, x, y, r, color, stroke) {
  ctx.beginPath();
  ctx.moveTo(x, y - r);
  ctx.lineTo(x + r * 0.78, y);
  ctx.lineTo(x, y + r);
  ctx.lineTo(x - r * 0.78, y);
  ctx.closePath();
  if (color) { ctx.fillStyle = color; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 1.2; ctx.stroke(); }
}

// ---------------------------------------------------------------------------
// main HUD
// ---------------------------------------------------------------------------
export function drawHUD(ctx, game) {
  if (game.phase === 'attract') return;
  const [p1, p2] = game.fighters;
  if (!p1 || !p2) return;

  const key = `${game.mode}-${game.round}-${game.charIds.join('-')}`;
  if (hudState.key !== key) {
    hudState.key = key;
    hudState.trail = [p1.health, p2.health];
  }

  for (let i = 0; i < 2; i++) {
    const f = game.fighters[i];
    if (f.health > hudState.trail[i]) hudState.trail[i] = f.health;
    else hudState.trail[i] += (f.health - hudState.trail[i]) * 0.09;
    hudState.ready[i] += ((f.spirit >= MAX_SPIRIT ? 1 : 0) - hudState.ready[i]) * 0.12;
    hudState.flash[i] = f.flash;
  }

  // top ornamental haze
  const topShade = ctx.createLinearGradient(0, 0, 0, 120);
  topShade.addColorStop(0, 'rgba(4, 3, 8, 0.82)');
  topShade.addColorStop(0.7, 'rgba(4, 3, 8, 0.35)');
  topShade.addColorStop(1, 'rgba(4, 3, 8, 0)');
  ctx.fillStyle = topShade;
  ctx.fillRect(0, 0, W, 124);
  const botShade = ctx.createLinearGradient(0, H - 80, 0, H);
  botShade.addColorStop(0, 'rgba(4, 3, 8, 0)');
  botShade.addColorStop(1, 'rgba(4, 3, 8, 0.76)');
  ctx.fillStyle = botShade;
  ctx.fillRect(0, H - 80, W, 80);

  drawHealthSide(ctx, game, 0, p1, hudState.trail[0]);
  drawHealthSide(ctx, game, 1, p2, hudState.trail[1]);

  drawTimer(ctx, game);
  drawSpirit(ctx, game, 0, p1);
  drawSpirit(ctx, game, 1, p2);
  drawCombo(ctx, game);

  // small reminder arc around P1 portrait during the first seconds
  if (game.round === 1 && game.phase === 'fight' && game.timer > 52 * 60) {
    // intentionally quiet
  }
}

function drawHealthSide(ctx, game, side, fighter, trail) {
  const char = CHARACTERS[fighter.charId];
  const c = char.colors;
  const mirror = side === 1;
  const x = mirror ? W - 100 - 466 : 100;
  const y = 46;
  const w = 466;
  const h = 27;
  const ratio = clamp(fighter.health / MAX_HEALTH, 0, 1);
  const trailRatio = clamp(trail / MAX_HEALTH, 0, 1);

  ctx.save();
  if (mirror) {
    ctx.translate(W, 0);
    ctx.scale(-1, 1);
  }

  const bx = 100;
  const by = y;

  // shadow / glow
  ctx.save();
  ctx.shadowColor = hexA(c.accent, 0.5);
  ctx.shadowBlur = 18 + hudState.ready[side] * 15;
  ctx.fillStyle = 'rgba(0,0,0,0)';
  ctx.fillRect(bx, by, w, h);
  ctx.restore();

  // frame
  const framePts = [
    [bx, by + 7], [bx + 9, by], [bx + w - 5, by], [bx + w, by + 6],
    [bx + w, by + h - 6], [bx + w - 8, by + h], [bx + 5, by + h], [bx, by + h - 5]
  ];
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.6)';
  ctx.shadowBlur = 10;
  ctx.shadowOffsetY = 3;
  ctx.fillStyle = 'rgba(8, 6, 13, 0.9)';
  poly(ctx, framePts);
  ctx.fill();
  ctx.restore();
  ctx.strokeStyle = 'rgba(216, 176, 106, 0.72)';
  ctx.lineWidth = 1.6;
  poly(ctx, framePts);
  ctx.stroke();
  ctx.strokeStyle = hexA(c.accent, 0.35);
  ctx.lineWidth = 1;
  poly(ctx, [[bx + 5, by + 4], [bx + w - 8, by + 4]]);
  ctx.stroke();

  // inner damage trail
  const innerX = bx + 4;
  const innerY = by + 4;
  const innerW = w - 8;
  const innerH = h - 8;
  ctx.save();
  ctx.beginPath();
  ctx.rect(innerX, innerY, innerW, innerH);
  ctx.clip();
  ctx.fillStyle = 'rgba(20, 12, 20, 0.9)';
  ctx.fillRect(innerX, innerY, innerW, innerH);
  // trail
  ctx.fillStyle = 'rgba(255, 214, 132, 0.6)';
  ctx.fillRect(innerX, innerY, innerW * trailRatio, innerH);
  // health
  const hg = ctx.createLinearGradient(innerX, innerY, innerX, innerY + innerH);
  hg.addColorStop(0, lighten(c.accent, 0.35));
  hg.addColorStop(0.42, c.accent);
  hg.addColorStop(1, darken(c.accent, 0.35));
  ctx.fillStyle = hg;
  ctx.fillRect(innerX, innerY, innerW * ratio, innerH);
  // top gloss
  ctx.fillStyle = 'rgba(255,255,255,0.26)';
  ctx.fillRect(innerX, innerY, innerW * ratio, 3);
  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  ctx.fillRect(innerX, innerY + innerH - 3, innerW * ratio, 3);
  // segment ticks
  ctx.strokeStyle = 'rgba(5, 3, 8, 0.45)';
  ctx.lineWidth = 1;
  for (let i = 1; i < 4; i++) {
    const sx = innerX + innerW * i / 4;
    ctx.beginPath();
    ctx.moveTo(sx, innerY);
    ctx.lineTo(sx - 4, innerY + innerH);
    ctx.stroke();
  }
  // hot edge
  if (ratio > 0) {
    ctx.fillStyle = 'rgba(255,255,255,0.55)';
    ctx.fillRect(innerX + innerW * ratio - 2, innerY, 2, innerH);
  }
  ctx.restore();

  // ready glow
  if (hudState.ready[side] > 0.02) {
    ctx.save();
    ctx.globalAlpha = hudState.ready[side] * 0.5;
    ctx.strokeStyle = c.accent2;
    ctx.lineWidth = 2;
    ctx.shadowColor = c.accent2;
    ctx.shadowBlur = 20;
    poly(ctx, framePts);
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();

  // portrait medallion (not mirrored)
  const px = mirror ? W - 58 : 58;
  drawPortrait(ctx, px, 58, fighter, mirror);

  // names / tags
  ctx.save();
  ctx.textBaseline = 'middle';
  ctx.textAlign = mirror ? 'right' : 'left';
  const nameX = mirror ? W - 100 : 100;
  ctx.font = `900 17px ${FONT}`;
  ctx.fillStyle = '#f5ead2';
  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = 8;
  ctx.fillText(spaced(char.name), nameX, 28);
  ctx.font = `700 8px ${FONT}`;
  ctx.fillStyle = hexA(c.accent2, 0.85);
  ctx.shadowBlur = 0;
  const tag = game.mode === 'local'
    ? (side === 0 ? 'PLAYER 1' : 'PLAYER 2')
    : (side === 0 ? 'PLAYER' : 'RIVAL');
  ctx.fillText(tag, nameX, 12);
  ctx.restore();

  // round pips
  for (let i = 0; i < 2; i++) {
    const got = game.wins[side] > i;
    const dx = mirror ? W - 112 - i * 20 : 112 + i * 20;
    diamond(ctx, dx, 90, 6.5, got ? c.accent2 : 'rgba(10,7,14,0.7)', got ? hexA('#fff3d0', 0.9) : 'rgba(216,176,106,0.55)');
    if (got) {
      ctx.save();
      ctx.globalAlpha = 0.5;
      ctx.shadowColor = c.accent2;
      ctx.shadowBlur = 10;
      diamond(ctx, dx, 90, 6.5, c.accent2, null);
      ctx.restore();
    }
  }
}

function drawPortrait(ctx, x, y, fighter, mirror) {
  const c = fighter.char.colors;
  ctx.save();
  ctx.translate(x, y);
  // glow
  const g = ctx.createRadialGradient(0, 0, 4, 0, 0, 44);
  g.addColorStop(0, hexA(c.accent, 0.44));
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, 44, 0, TAU);
  ctx.fill();

  ctx.fillStyle = 'rgba(10, 7, 14, 0.95)';
  ctx.beginPath();
  ctx.arc(0, 0, 32, 0, TAU);
  ctx.fill();
  const ig = ctx.createLinearGradient(-18, -22, 18, 22);
  ig.addColorStop(0, darken(c.accent, 0.2));
  ig.addColorStop(1, '#0a0710');
  ctx.fillStyle = ig;
  ctx.beginPath();
  ctx.arc(0, 0, 27, 0, TAU);
  ctx.fill();

  // kanji sigil
  ctx.font = `700 25px ${JP}`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = hexA(c.accent2, fighter.spirit >= 100 ? 1 : 0.85);
  if (fighter.spirit >= 100) {
    ctx.shadowColor = c.accent2;
    ctx.shadowBlur = 16;
  }
  ctx.fillText(CHARACTERS[fighter.charId].kanji, 1, 1);
  ctx.shadowBlur = 0;

  ctx.strokeStyle = 'rgba(216, 176, 106, 0.8)';
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.arc(0, 0, 30.5, 0, TAU);
  ctx.stroke();
  ctx.strokeStyle = hexA(c.accent, 0.6);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(0, 0, 24, -0.8, 0.8);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(0, 0, 24, Math.PI - 0.8, Math.PI + 0.8);
  ctx.stroke();
  if (fighter.flash > 0.1) {
    ctx.globalAlpha = fighter.flash * 0.5;
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(0, 0, 27, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawTimer(ctx, game) {
  const sec = Math.max(0, Math.ceil(game.timer / 60));
  const low = sec <= 10 && game.phase === 'fight';
  const pulse = low ? 0.5 + 0.5 * Math.sin(game.time * 9) : 0;
  const cx = W / 2;
  const y = 28;

  ctx.save();
  // frame
  ctx.translate(cx, y);
  const pts = [[-50, 0], [-38, -8], [38, -8], [50, 0], [44, 62], [0, 72], [-44, 62]];
  ctx.fillStyle = 'rgba(7, 5, 12, 0.9)';
  poly(ctx, pts);
  ctx.fill();
  ctx.strokeStyle = low ? `rgba(255, 100, 90, ${0.7 + pulse * 0.3})` : 'rgba(216,176,106,0.75)';
  ctx.lineWidth = 1.8;
  ctx.shadowColor = low ? '#ea4d4d' : 'rgba(216,176,106,0.6)';
  ctx.shadowBlur = low ? 18 : 8;
  poly(ctx, pts);
  ctx.stroke();
  ctx.shadowBlur = 0;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `900 43px ${FONT}`;
  const tg = ctx.createLinearGradient(0, 8, 0, 52);
  tg.addColorStop(0, '#fff6dd');
  tg.addColorStop(0.55, low ? '#ffb0a0' : '#f6dfac');
  tg.addColorStop(1, low ? '#ff514c' : '#c89a51');
  ctx.fillStyle = tg;
  ctx.shadowColor = 'rgba(0,0,0,0.9)';
  ctx.shadowBlur = 6;
  ctx.shadowOffsetY = 2;
  ctx.fillText(String(sec).padStart(2, '0'), 0, 28);
  ctx.shadowBlur = 0;
  ctx.shadowOffsetY = 0;

  ctx.font = `700 7px ${FONT}`;
  ctx.fillStyle = 'rgba(216,176,106,0.7)';
  ctx.fillText('TIME', 0, 57);

  // round tag under timer
  ctx.font = `800 8px ${FONT}`;
  ctx.fillStyle = 'rgba(240, 227, 202, 0.72)';
  ctx.fillText(`ROUND ${game.round}`, 0, 89);
  ctx.restore();
}

function drawSpirit(ctx, game, side, fighter) {
  const c = fighter.char.colors;
  const mirror = side === 1;
  const x = mirror ? W - 100 - 268 : 100;
  const y = 678;
  const w = 268;
  const h = 12;
  const ratio = clamp(fighter.spirit / MAX_SPIRIT, 0, 1);
  const ready = hudState.ready[side];

  ctx.save();
  // frame
  ctx.fillStyle = 'rgba(8, 6, 13, 0.78)';
  poly(ctx, [[x, y], [x + w, y], [x + w - 5, y + h], [x + 5, y + h]]);
  ctx.fill();
  ctx.strokeStyle = ready > 0.5 ? hexA(c.accent2, 0.9) : 'rgba(216,176,106,0.4)';
  ctx.lineWidth = 1.2;
  poly(ctx, [[x, y], [x + w, y], [x + w - 5, y + h], [x + 5, y + h]]);
  ctx.stroke();

  // fill
  const fw = (w - 8) * ratio;
  if (fw > 0) {
    const g = ctx.createLinearGradient(x, y, x + w, y);
    g.addColorStop(0, c.accent);
    g.addColorStop(0.65, c.accent2);
    g.addColorStop(1, '#fff6d6');
    ctx.fillStyle = g;
    ctx.fillRect(x + 4, y + 3, fw, h - 6);
    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    ctx.fillRect(x + 4, y + 3, fw, 2);
  }
  // segments
  ctx.strokeStyle = 'rgba(6,4,9,0.45)';
  ctx.lineWidth = 1;
  for (let i = 1; i < 5; i++) {
    const sx = x + 4 + (w - 8) * i / 5;
    ctx.beginPath();
    ctx.moveTo(sx, y + 2);
    ctx.lineTo(sx - 2, y + h - 2);
    ctx.stroke();
  }

  if (ready > 0.5) {
    ctx.globalAlpha = 0.25 + 0.35 * Math.abs(Math.sin(game.time * 3));
    ctx.shadowColor = c.accent2;
    ctx.shadowBlur = 18;
    ctx.strokeStyle = c.accent2;
    ctx.lineWidth = 2;
    poly(ctx, [[x, y], [x + w, y], [x + w - 5, y + h], [x + 5, y + h]]);
    ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.globalAlpha = 1;
  }

  // labels
  ctx.font = `800 8px ${FONT}`;
  ctx.textAlign = mirror ? 'right' : 'left';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = ready > 0.5 ? c.accent2 : 'rgba(216,176,106,0.65)';
  const lx = mirror ? x + w : x;
  ctx.fillText('SPIRIT', lx, y - 9);
  if (ready > 0.5) {
    ctx.textAlign = mirror ? 'left' : 'right';
    ctx.fillStyle = hexA(c.accent2, 0.7 + 0.3 * Math.sin(game.time * 5));
    ctx.fillText('SUPER READY', mirror ? x : x + w, y - 9);
  }
  ctx.restore();
}

function drawCombo(ctx, game) {
  if (game.combo.timer <= 0 || game.combo.count < 2) return;
  const side = game.combo.side;
  const f = game.fighters[side];
  const c = f.char.colors;
  const life = game.combo.timer / 88;
  const x = side === 0 ? 250 : W - 250;
  const y = 190;
  const pop = 1 + Math.max(0, (game.combo.timer - 72) / 20) * 0.28;

  ctx.save();
  ctx.translate(x, y);
  ctx.scale(pop, pop);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.globalAlpha = clamp(life * 1.4, 0, 1);
  ctx.font = `italic 900 64px ${SERIF}`;
  ctx.fillStyle = '#fff4d8';
  ctx.strokeStyle = hexA(c.accent, 0.9);
  ctx.lineWidth = 2;
  ctx.shadowColor = hexA(c.accent, 0.8);
  ctx.shadowBlur = 18;
  ctx.strokeText(String(game.combo.count), 0, 0);
  ctx.fillText(String(game.combo.count), 0, 0);
  ctx.shadowBlur = 0;
  ctx.font = `900 15px ${FONT}`;
  ctx.fillStyle = c.accent2;
  ctx.fillText('HIT COMBO', 0, 42);
  // side slashes
  ctx.strokeStyle = hexA(c.accent, 0.55 * life);
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-62, -20);
  ctx.lineTo(-18, 20);
  ctx.moveTo(62, -20);
  ctx.lineTo(18, 20);
  ctx.stroke();
  ctx.restore();
}

// ---------------------------------------------------------------------------
// callouts and round banners
// ---------------------------------------------------------------------------
export function drawCallout(ctx, game) {
  const c = game.callout;
  if (!c) return;
  const p = 1 - c.timer / c.max;
  const fadeIn = clamp(p / 0.12, 0, 1);
  const fadeOut = clamp(c.timer / 16, 0, 1);
  const alpha = fadeIn * fadeOut;
  const side = c.side;
  const dir = side === 0 ? 1 : -1;
  const y = c.big ? 378 : 492;

  ctx.save();
  ctx.globalAlpha = alpha;

  if (c.big) {
    // cinematic letterbox
    const top = ctx.createLinearGradient(0, 230, 0, 320);
    top.addColorStop(0, 'rgba(3,2,7,0)');
    top.addColorStop(1, 'rgba(3,2,7,0.88)');
    ctx.fillStyle = top;
    ctx.fillRect(0, 230, W, 92);
    const bottom = ctx.createLinearGradient(0, 460, 0, 550);
    bottom.addColorStop(0, 'rgba(3,2,7,0.88)');
    bottom.addColorStop(1, 'rgba(3,2,7,0)');
    ctx.fillStyle = bottom;
    ctx.fillRect(0, 460, W, 92);

    // radial ink burst
    ctx.save();
    ctx.translate(W / 2, y);
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 18; i++) {
      const a = i / 18 * TAU + game.time * 0.2;
      const len = 220 + Math.sin(i * 2.4) * 90;
      ctx.fillStyle = hexA(i % 2 ? c.color : '#ffffff', 0.04);
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(Math.cos(a - 0.02) * len, Math.sin(a - 0.02) * len);
      ctx.lineTo(Math.cos(a + 0.02) * len, Math.sin(a + 0.02) * len);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    // giant kanji watermark
    const char = game.fighters[side]?.char ?? CHARACTERS.kaito;
    ctx.save();
    ctx.globalAlpha = alpha * 0.1;
    ctx.fillStyle = c.color;
    ctx.font = `700 210px ${JP}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(char.kanji, W / 2, y + 8);
    ctx.restore();
  }

  // accent lines
  ctx.strokeStyle = hexA(c.color, 0.8);
  ctx.lineWidth = 1.6;
  const lineW = c.big ? 300 : 150;
  ctx.beginPath();
  ctx.moveTo(W / 2 - lineW, y + 14);
  ctx.lineTo(W / 2 - 80, y + 14);
  ctx.moveTo(W / 2 + 80, y + 14);
  ctx.lineTo(W / 2 + lineW, y + 14);
  ctx.stroke();

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  ctx.font = `800 ${c.big ? 13 : 10}px ${FONT}`;
  ctx.fillStyle = hexHue(c.color, 0.9);
  ctx.fillText(c.sub, W / 2, y - (c.big ? 38 : 30));

  const size = c.big ? 58 : 40;
  ctx.font = `900 ${size}px ${FONT}`;
  const g = ctx.createLinearGradient(0, y - size / 2, 0, y + size / 2);
  g.addColorStop(0, '#fff9e8');
  g.addColorStop(0.5, c.color);
  g.addColorStop(1, darken(c.color, 0.4));
  ctx.fillStyle = g;
  ctx.strokeStyle = 'rgba(5, 3, 8, 0.9)';
  ctx.lineWidth = 5;
  ctx.shadowColor = c.color;
  ctx.shadowBlur = 22;
  ctx.strokeText(c.text, W / 2, y + 12);
  ctx.fillText(c.text, W / 2, y + 12);
  ctx.shadowBlur = 0;

  // sliding sheen
  const sheen = ((game.time * 0.5) % 1) * 420 - 210;
  ctx.save();
  ctx.beginPath();
  ctx.rect(W / 2 - 200, y - 20, 400, 60);
  ctx.clip();
  ctx.globalAlpha = alpha * 0.28;
  ctx.translate(W / 2 + sheen, y + 12);
  ctx.rotate(-0.3);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(-8, -50, 16, 100);
  ctx.restore();

  ctx.restore();
}

export function drawBanner(ctx, game) {
  if (game.phase === 'intro') {
    const t = game.phaseTimer;
    if (t < 70) {
      const a = clamp(t / 8, 0, 1) * clamp((70 - t) / 12, 0, 1);
      drawRoundBanner(ctx, `ROUND ${game.round}`, `第 ${game.round} 番`, a, 1 + (1 - clamp(t / 70, 0, 1)) * 0.05);
    } else {
      const p = clamp((t - 70) / 48, 0, 1);
      const a = clamp((t - 70) / 7, 0, 1) * clamp((118 - t) / 8, 0, 1);
      drawFightBanner(ctx, a, p);
    }
    return;
  }

  if (game.phase === 'ko') {
    const t = game.phaseTimer;
    if (t < 108) {
      const a = clamp(t / 6, 0, 1) * clamp((108 - t) / 15, 0, 1);
      if (game.roundReason === 'TIME') {
        drawKOBanner(ctx, 'TIME OVER', '時間切れ', a, '#ffd489', game);
      } else if (game.roundWinner < 0) {
        drawKOBanner(ctx, 'DRAW', '引き分け', a, '#d8d0c0', game);
      } else {
        drawKOBanner(ctx, 'K.O.', '決着', a, '#ff7064', game);
        const w = game.fighters[game.roundWinner];
        if (w && w.health >= MAX_HEALTH - 0.1) {
          ctx.save();
          ctx.globalAlpha = a * 0.9;
          ctx.font = `900 16px ${FONT}`;
          ctx.textAlign = 'center';
          ctx.fillStyle = '#ffe3a3';
          ctx.shadowColor = '#ffb04e';
          ctx.shadowBlur = 16;
          ctx.fillText('PERFECT', W / 2, 240);
          ctx.restore();
        }
      }
    }
  }
}

function drawRoundBanner(ctx, text, jp, alpha, scale) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(W / 2, 330);
  ctx.scale(scale, scale);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  ctx.font = `700 16px ${JP}`;
  ctx.fillStyle = 'rgba(255, 227, 163, 0.75)';
  ctx.fillText(jp, 0, -62);

  // ink slash behind
  ctx.save();
  ctx.globalAlpha = alpha * 0.7;
  ctx.fillStyle = 'rgba(9, 6, 14, 0.55)';
  ctx.beginPath();
  ctx.moveTo(-280, 4);
  ctx.lineTo(250, -22);
  ctx.lineTo(290, 6);
  ctx.lineTo(-250, 30);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  const g = ctx.createLinearGradient(0, -50, 0, 54);
  g.addColorStop(0, '#fff8e4');
  g.addColorStop(0.45, '#efd39a');
  g.addColorStop(1, '#b47732');
  ctx.font = `900 76px ${SERIF}`;
  ctx.fillStyle = g;
  ctx.strokeStyle = 'rgba(7, 5, 11, 0.92)';
  ctx.lineWidth = 7;
  ctx.shadowColor = 'rgba(214, 60, 74, 0.55)';
  ctx.shadowBlur = 30;
  ctx.strokeText(text, 0, 0);
  ctx.fillText(text, 0, 0);
  ctx.shadowBlur = 0;

  ctx.strokeStyle = 'rgba(216,176,106,0.7)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(-240, 44);
  ctx.lineTo(-70, 44);
  ctx.moveTo(70, 44);
  ctx.lineTo(240, 44);
  ctx.stroke();
  ctx.restore();
}

function drawFightBanner(ctx, alpha, progress) {
  const scale = 0.72 + Math.min(1, progress * 4) * 0.36;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(W / 2, 332);
  ctx.scale(scale, scale);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // speed slashes
  ctx.save();
  ctx.globalAlpha = alpha * 0.6;
  for (let i = -3; i <= 3; i++) {
    ctx.fillStyle = i % 2 ? 'rgba(255, 220, 150, 0.11)' : 'rgba(214, 60, 74, 0.14)';
    ctx.beginPath();
    ctx.moveTo(-420 + i * 30, -70 + i * 8);
    ctx.lineTo(380 + i * 30, -90 + i * 8);
    ctx.lineTo(400 + i * 30, -74 + i * 8);
    ctx.lineTo(-400 + i * 30, -54 + i * 8);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();

  const g = ctx.createLinearGradient(0, -60, 0, 62);
  g.addColorStop(0, '#fff5d1');
  g.addColorStop(0.4, '#ffb44f');
  g.addColorStop(0.72, '#e0443f');
  g.addColorStop(1, '#791522');
  ctx.font = `900 118px ${FONT}`;
  ctx.fillStyle = g;
  ctx.strokeStyle = 'rgba(6, 4, 9, 0.95)';
  ctx.lineWidth = 9;
  ctx.shadowColor = 'rgba(255, 100, 50, 0.7)';
  ctx.shadowBlur = 38;
  ctx.strokeText('FIGHT!', 0, 0);
  ctx.fillText('FIGHT!', 0, 0);
  ctx.shadowBlur = 0;

  ctx.font = `700 15px ${JP}`;
  ctx.fillStyle = 'rgba(255, 235, 197, 0.7)';
  ctx.fillText('始 め', 0, 78);
  ctx.restore();
}

function drawKOBanner(ctx, text, jp, alpha, color, game) {
  const t = game.phaseTimer;
  const scale = 1.5 - clamp(t / 8, 0, 1) * 0.5;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(W / 2, 330);
  ctx.scale(scale, scale);

  // brush strokes behind
  ctx.save();
  ctx.globalAlpha = alpha * 0.8;
  for (let i = 0; i < 3; i++) {
    ctx.fillStyle = i === 0 ? 'rgba(150, 22, 34, 0.35)' : 'rgba(14, 8, 16, 0.55)';
    ctx.beginPath();
    ctx.moveTo(-330 + i * 40, -40 + i * 23);
    ctx.lineTo(280 + i * 25, -66 + i * 23);
    ctx.lineTo(340 + i * 20, -42 + i * 23);
    ctx.lineTo(-290 + i * 40, -8 + i * 23);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  const size = text.length > 5 ? 96 : 132;
  const g = ctx.createLinearGradient(0, -60, 0, 66);
  g.addColorStop(0, '#fff8e8');
  g.addColorStop(0.35, color);
  g.addColorStop(1, darken(color, 0.45));
  ctx.font = `900 ${size}px ${FONT}`;
  ctx.fillStyle = g;
  ctx.strokeStyle = 'rgba(6, 4, 9, 0.95)';
  ctx.lineWidth = 10;
  ctx.shadowColor = hexA(color, 0.8);
  ctx.shadowBlur = 40;
  ctx.strokeText(text, 0, 0);
  ctx.fillText(text, 0, 0);
  ctx.shadowBlur = 0;

  ctx.font = `700 16px ${JP}`;
  ctx.fillStyle = 'rgba(255, 235, 197, 0.65)';
  ctx.fillText(jp, 0, 84);
  ctx.restore();
}

// ---------------------------------------------------------------------------
// screen treatment
// ---------------------------------------------------------------------------
export function drawScreenFX(ctx, game) {
  // low-health edges
  for (let i = 0; i < 2; i++) {
    const f = game.fighters[i];
    if (!f || f.health > 30 || game.phase === 'attract') continue;
    const intensity = (1 - f.health / 30) * (0.5 + 0.5 * Math.sin(game.time * 5));
    const x0 = i === 0 ? 0 : W;
    const x1 = i === 0 ? 260 : W - 260;
    const g = ctx.createLinearGradient(x0, 0, x1, 0);
    g.addColorStop(0, `rgba(150, 14, 24, ${0.24 * intensity})`);
    g.addColorStop(1, 'rgba(150, 14, 24, 0)');
    ctx.fillStyle = g;
    ctx.fillRect(i === 0 ? 0 : W - 260, 120, 260, H - 200);
  }

  // speed lines during KOs and supers
  const speed = game.phase === 'ko' ? clamp((60 - game.phaseTimer) / 60, 0, 1) : game.superCine > 0 ? game.superCine / 60 * 0.4 : 0;
  if (speed > 0) {
    ctx.save();
    ctx.globalAlpha = speed * 0.5;
    ctx.strokeStyle = '#ffe0ad';
    ctx.translate(W / 2, H / 2);
    for (let i = 0; i < 36; i++) {
      const a = i / 36 * TAU + (i % 3) * 0.03;
      const r0 = 240 + (i % 5) * 20;
      const r1 = r0 + 180 + (i % 4) * 90;
      ctx.lineWidth = 1 + (i % 3) * 0.6;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * r0, Math.sin(a) * r0);
      ctx.lineTo(Math.cos(a) * r1, Math.sin(a) * r1);
      ctx.stroke();
    }
    ctx.restore();
  }

  // vignette
  const v = ctx.createRadialGradient(W / 2, H * 0.45, H * 0.28, W / 2, H * 0.45, W * 0.72);
  v.addColorStop(0, 'rgba(0,0,0,0)');
  v.addColorStop(0.75, 'rgba(0,0,0,0.16)');
  v.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, W, H);

  // color flash
  if (game.flash > 0.01) {
    ctx.save();
    ctx.globalAlpha = clamp(game.flash, 0, 0.85);
    ctx.fillStyle = game.flashColor;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }
}

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------
function spaced(text) {
  return text.split('').join('\u200a');
}

function lighten(hex, amount) {
  return shade(hex, amount);
}
function darken(hex, amount) {
  return shade(hex, -amount);
}
function hexHue(hex, alpha) {
  return hexA(hex, alpha);
}
function shade(hex, amount) {
  let h = hex.replace('#', '');
  if (h.length === 3) h = h.split('').map((c) => c + c).join('');
  const n = parseInt(h, 16);
  let r = (n >> 16) & 255;
  let g = (n >> 8) & 255;
  let b = n & 255;
  if (amount > 0) {
    r += (255 - r) * amount;
    g += (255 - g) * amount;
    b += (255 - b) * amount;
  } else {
    r *= 1 + amount;
    g *= 1 + amount;
    b *= 1 + amount;
  }
  return `rgb(${Math.round(r)}, ${Math.round(g)}, ${Math.round(b)})`;
}

